#include "apex/tracking.hpp"
#include <windows.h>
#include <fstream>
#include <iostream>
void pump(){for(int i=0;i<10;++i){MSG m{};while(PeekMessageW(&m,nullptr,0,0,PM_REMOVE)){TranslateMessage(&m);DispatchMessageW(&m);}Sleep(10);}}
struct Cleanup{HWND h=nullptr;POINT cursor{};Cleanup(){GetCursorPos(&cursor);}~Cleanup(){INPUT keyUp{};keyUp.type=INPUT_KEYBOARD;keyUp.ki.wVk=VK_LSHIFT;keyUp.ki.dwFlags=KEYEVENTF_KEYUP;SendInput(1,&keyUp,sizeof(keyUp));INPUT up{};up.type=INPUT_MOUSE;up.mi.dwFlags=MOUSEEVENTF_RIGHTUP;SendInput(1,&up,sizeof(up));SetCursorPos(cursor.x,cursor.y);if(h)DestroyWindow(h);UnregisterClassW(L"ApexTrackingInputProbe",GetModuleHandleW(nullptr));}};
int main(){Cleanup cleanup;std::ofstream report("tracking-input-probe.txt");auto skip=[&](const std::string& reason){report<<"SKIPPED actual desktop input probe: "<<reason<<"; requires an interactive PC test; no Apex acceptance claim\n";std::cout<<reason<<'\n';return 77;};WNDCLASSW wc{};wc.lpfnWndProc=DefWindowProcW;wc.hInstance=GetModuleHandleW(nullptr);wc.lpszClassName=L"ApexTrackingInputProbe";if(!RegisterClassW(&wc))return skip("Window class unavailable");cleanup.h=CreateWindowExW(0,wc.lpszClassName,L"Apex input probe (own validation window)",WS_OVERLAPPEDWINDOW,100,100,600,400,nullptr,nullptr,wc.hInstance,nullptr);if(!cleanup.h)return skip("Own test window unavailable");ShowWindow(cleanup.h,SW_SHOW);SetForegroundWindow(cleanup.h);pump();apex::TrackingWindow selected{reinterpret_cast<std::uintptr_t>(cleanup.h),GetCurrentProcessId(),"Apex input probe"};auto state=apex::inspectTrackingWindow(selected);if(!state.valid||!state.focused)return skip("Hosted desktop did not grant own-window focus");POINT point{300,250};ClientToScreen(cleanup.h,&point);SetCursorPos(point.x,point.y);INPUT down{};down.type=INPUT_MOUSE;down.mi.dwFlags=MOUSEEVENTF_RIGHTDOWN;if(SendInput(1,&down,sizeof(down))!=1)return skip("Windows rejected right-button test event");pump();state=apex::inspectTrackingWindow(selected);if(!state.hold)return skip("Hosted desktop did not expose button hold");POINT before{},after{};GetCursorPos(&before);std::string error;if(!apex::sendTrackingMovement(selected,2,1,error))return skip(error);pump();GetCursorPos(&after);if(after.x<=before.x||after.y<before.y)return skip("SendInput returned accepted but cursor displacement was not verified");INPUT up{};up.type=INPUT_MOUSE;up.mi.dwFlags=MOUSEEVENTF_RIGHTUP;if(SendInput(1,&up,sizeof(up))!=1)return skip("Could not verify release event");pump();if((GetAsyncKeyState(VK_RBUTTON)&0x8000)||!SetCursorPos(cleanup.cursor.x,cleanup.cursor.y))return skip("Button/cursor restore could not be verified");apex::TrackingOptions toggle;toggle.armed=true;toggle.activationMode=apex::TrackingActivationMode::Toggle;SetCursorPos(point.x,point.y);GetCursorPos(&before);if(!apex::sendTrackingMovement(selected,2,1,toggle,true,error))return skip(error);pump();GetCursorPos(&after);if(after.x<=before.x)return skip("Toggle-mode accepted event displacement not observed");toggle.armed=false;if(apex::sendTrackingMovement(selected,2,1,toggle,true,error))return skip("Disarmed toggle was not blocked");toggle.armed=true;if(apex::sendTrackingMovement(selected,2,1,toggle,false,error))return skip("Inactive toggle was not blocked");apex::TrackingOptions shift;shift.armed=true;shift.activationKey=apex::TrackingActivationKey::LeftShift;if(apex::sendTrackingMovement(selected,2,1,shift,true,error))return skip("Unheld Shift binding was not blocked");INPUT key{};key.type=INPUT_KEYBOARD;key.ki.wVk=VK_LSHIFT;if(SendInput(1,&key,sizeof(key))!=1)return skip("Windows rejected Shift test key");pump();if(!apex::trackingActivationDown(shift.activationKey)||!apex::sendTrackingMovement(selected,2,1,shift,true,error))return skip("Held Shift binding was not verified: "+error);key.ki.dwFlags=KEYEVENTF_KEYUP;if(SendInput(1,&key,sizeof(key))!=1)return skip("Shift release failed");pump();if(apex::trackingActivationDown(shift.activationKey)||!SetCursorPos(cleanup.cursor.x,cleanup.cursor.y))return skip("Shift/cursor restore not verified");report<<"PASS actual Windows SendInput through default Hold, explicit Toggle and held Left Shift binding guards in OWN test window; inactive/disarmed toggle and unheld Shift rejected; observed toggle cursor delta="<<after.x-before.x<<","<<after.y-before.y<<"; button/Shift released and cursor restored; no live game, Apex acceptance, trained-model GPU or aim accuracy tested\n";std::cout<<"PASS actual guarded desktop mouse event\n";return 0;}
